class Solution {
public:
    int minimumDeletions(vector<int>& nums) {
        int n = nums.size();
        int minIdx = 0, maxIdx = 0;
        for (int k = 1; k < n; k++) {
            if (nums[k] < nums[minIdx]) minIdx = k;
            if (nums[k] > nums[maxIdx]) maxIdx = k;
        }
        int lo = min(minIdx, maxIdx);
        int hi = max(minIdx, maxIdx);
        return min({hi + 1, n - lo, (lo + 1) + (n - hi)});
    }
};
